@6 n="mean_valence_f_subshell_occupancy" d="Composition-weighted f occupancy in the supplied valence-subshell convention." B=631
def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    value = 0.0
    total = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        shell = (props.get(element) or {}).get('pymatgen_valence_subshell')
        if fraction is not None and fraction > 0 and shell is not None and len(shell) == 2:
            l = shell[0]
            count = shell[1]
